  "abc163-c": { java: "class Solution {\n    public int[] directReports(int[] a) {\n        int[] cnt = new int[a.length + 1];\n        for (int b : a) cnt[b - 1]++;\n        return cnt;\n    }\n}\n", python: "from typing import List\n\nclass Solution:\n    def directReports(self, a: List[int]) -> List[int]:\n        cnt = [0] * (len(a) + 1)\n        for b in a:\n            cnt[b - 1] += 1\n        return cnt\n" },
  "abc164-c": { java: "import java.util.Collections;\nimport java.util.HashSet;\nimport java.util.Set;\n\nclass Solution {\n    public int kindsOfItems(String[] s) {\n        Set<String> seen = new HashSet<>();\n        Collections.addAll(seen, s);\n        return seen.size();\n    }\n}\n", python: "from typing import List\n\nclass Solution:\n    def kindsOfItems(self, s: List[str]) -> int:\n        return len(set(s))\n" },
